import {campaignNarrative} from '../shared/campaign-narrator-model.mjs';
import {CAMPAIGN_NPCS,campaignNpcsForRealm,campaignNpcUrl,campaignNpcEvent} from '../shared/campaign-cast.mjs';
import {campaignArtifact} from '../shared/campaign-artifacts.mjs';
